// Writes the shared commands and the trigger events, from commands.json, as Go for the manifest check
// and as TypeScript for the SDK. Run by `make lib_protocol_generate`; the generated files are committed.
import { readFileSync, writeFileSync } from 'node:fs'
import { fileURLToPath } from 'node:url'

const read = (path) => readFileSync(fileURLToPath(new URL(path, import.meta.url)), 'utf8')
const write = (path, text) => writeFileSync(fileURLToPath(new URL(path, import.meta.url)), text)

const { commands, events } = JSON.parse(read('../commands.json'))
const HEADER =
  'Code generated by libs/protocol/tools/commands.mjs from libs/protocol/commands.json. DO NOT EDIT.'
const quoted = (list) => list.map((one) => JSON.stringify(one)).join(', ')

const go = [
  `// ${HEADER}`,
  '',
  'package manifest',
  '',
  '// IsSharedCommand reports whether the full id is a shared command of the application, which plugins',
  '// handle in contributes.handlers.',
  'func IsSharedCommand(id string) bool {',
  '\tswitch id {',
  `\tcase ${quoted(commands.map((one) => one.id))}:`,
  '\t\treturn true',
  '\t}',
  '\treturn false',
  '}',
  '',
  '// IsTriggerEvent reports whether the name is an event a trigger in contributes.triggers runs on.',
  'func IsTriggerEvent(name string) bool {',
  '\tswitch name {',
  `\tcase ${quoted(events.map((one) => one.name))}:`,
  '\t\treturn true',
  '\t}',
  '\treturn false',
  '}',
  '',
].join('\n')

const ts = [
  `// ${HEADER}`,
  '',
  '// SHARED_COMMANDS are the shared commands of the application: plugins handle them in',
  '// contributes.handlers. `items` says where the items of the command come from.',
  'export const SHARED_COMMANDS = [',
  ...commands.map(
    (one) => `  { id: '${one.id}', title: '${one.title}', items: '${one.items}' },`,
  ),
  '] as const',
  '',
  '// TRIGGER_EVENTS are the events a trigger in contributes.triggers runs on.',
  `export const TRIGGER_EVENTS = [${events.map((one) => `'${one.name}'`).join(', ')}] as const`,
  '',
].join('\n')

write('../../plugin-catalog/manifest/shared_commands.go', go)
write('../../plugin-sdk-ts/src/slots/sharedCommands.ts', ts)
